"""Conway's Game of Life, every generation computed by a wgpu compute shader."""

import sys

import numpy as np
import wgpu

WORKGROUP = 8

SHADER = f"""
struct Dims {{
    width: u32,
    height: u32,
}};

@group(0) @binding(0) var<uniform> dims: Dims;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

fn cell(x: i32, y: i32) -> u32 {{
    if (x < 0 || y < 0 || x >= i32(dims.width) || y >= i32(dims.height)) {{
        return 0u;
    }}
    return src[u32(y) * dims.width + u32(x)];
}}

@compute @workgroup_size({WORKGROUP}, {WORKGROUP})
fn step(@builtin(global_invocation_id) id: vec3<u32>) {{
    if (id.x >= dims.width || id.y >= dims.height) {{
        return;
    }}
    let x = i32(id.x);
    let y = i32(id.y);
    let n = cell(x - 1, y - 1) + cell(x, y - 1) + cell(x + 1, y - 1)
          + cell(x - 1, y)                      + cell(x + 1, y)
          + cell(x - 1, y + 1) + cell(x, y + 1) + cell(x + 1, y + 1);
    let alive = cell(x, y);
    var next = 0u;
    if (n == 3u || (alive == 1u && n == 2u)) {{
        next = 1u;
    }}
    dst[id.y * dims.width + id.x] = next;
}}
"""


def parse(text):
    tokens = text.split()
    width, height, generations = int(tokens[0]), int(tokens[1]), int(tokens[2])
    cells = tokens[3 : 3 + width * height]
    if len(cells) != width * height:
        raise ValueError(f"expected {width * height} cells, got {len(cells)}")
    grid = np.array([1 if c == "1" else 0 for c in cells], dtype=np.uint32)
    return width, height, generations, grid.reshape(height, width)


def run_gpu(grid, generations):
    height, width = grid.shape
    if generations == 0:
        return grid.copy()

    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = adapter.request_device_sync()

    size = grid.nbytes
    storage = wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC | wgpu.BufferUsage.COPY_DST
    buffers = [device.create_buffer(size=size, usage=storage) for _ in range(2)]
    device.queue.write_buffer(buffers[0], 0, np.ascontiguousarray(grid).tobytes())

    dims = device.create_buffer(size=16, usage=wgpu.BufferUsage.UNIFORM | wgpu.BufferUsage.COPY_DST)
    device.queue.write_buffer(dims, 0, np.array([width, height, 0, 0], dtype=np.uint32).tobytes())

    shader = device.create_shader_module(code=SHADER)
    layout = device.create_bind_group_layout(
        entries=[
            {"binding": 0, "visibility": wgpu.ShaderStage.COMPUTE,
             "buffer": {"type": wgpu.BufferBindingType.uniform}},
            {"binding": 1, "visibility": wgpu.ShaderStage.COMPUTE,
             "buffer": {"type": wgpu.BufferBindingType.read_only_storage}},
            {"binding": 2, "visibility": wgpu.ShaderStage.COMPUTE,
             "buffer": {"type": wgpu.BufferBindingType.storage}},
        ]
    )
    pipeline = device.create_compute_pipeline(
        layout=device.create_pipeline_layout(bind_group_layouts=[layout]),
        compute={"module": shader, "entry_point": "step"},
    )

    # bind_groups[i] reads buffers[i] and writes buffers[1 - i].
    bind_groups = [
        device.create_bind_group(
            layout=layout,
            entries=[
                {"binding": 0, "resource": {"buffer": dims, "offset": 0, "size": 16}},
                {"binding": 1, "resource": {"buffer": buffers[i], "offset": 0, "size": size}},
                {"binding": 2, "resource": {"buffer": buffers[1 - i], "offset": 0, "size": size}},
            ],
        )
        for i in range(2)
    ]

    groups_x = (width + WORKGROUP - 1) // WORKGROUP
    groups_y = (height + WORKGROUP - 1) // WORKGROUP
    encoder = device.create_command_encoder()
    for g in range(generations):
        # Separate passes so each generation sees the complete previous one.
        compute = encoder.begin_compute_pass()
        compute.set_pipeline(pipeline)
        compute.set_bind_group(0, bind_groups[g % 2])
        compute.dispatch_workgroups(groups_x, groups_y, 1)
        compute.end()
    device.queue.submit([encoder.finish()])

    result = device.queue.read_buffer(buffers[generations % 2])
    return np.frombuffer(result, dtype=np.uint32).reshape(height, width).copy()


def main(argv):
    if len(argv) < 2:
        print("usage: main.py <input-file>", file=sys.stderr)
        return 2
    with open(argv[1]) as f:
        width, height, generations, grid = parse(f.read())
    final = run_gpu(grid, generations)
    lines = [" ".join("1" if v else "0" for v in row) for row in final]
    lines.append(f"ALIVE {int(np.count_nonzero(final))}")
    sys.stdout.write("\n".join(lines) + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

